create table public.poem_contest_reservations (
 id uuid primary key default gen_random_uuid(),cycle text not null default '2026-2027' check(cycle='2026-2027'),
 student_id text not null references public.poem_contest_roster(id),group_key text not null,
 poem_number integer not null references public.poem_contest_catalog(number),
 canonical_number integer generated always as (case when poem_number=16 then 9 else poem_number end) stored,
 active boolean not null default true,chosen_at timestamptz not null default now(),released_at timestamptz,created_by uuid not null default auth.uid()
);
create unique index poem_contest_group_unique on public.poem_contest_reservations(cycle,group_key,canonical_number) where active;
create unique index poem_contest_student_unique on public.poem_contest_reservations(cycle,student_id) where active;
alter table public.poem_contest_catalog enable row level security;
alter table public.poem_contest_reservations enable row level security;
revoke all on public.poem_contest_catalog,public.poem_contest_reservations from anon,authenticated;
grant select on public.poem_contest_catalog to authenticated;
grant select,insert,update on public.poem_contest_reservations to authenticated;
create policy poem_catalog_teacher on public.poem_contest_catalog for select to authenticated using(public.is_teacher());
create policy poem_reservations_teacher on public.poem_contest_reservations for all to authenticated
 using(public.is_teacher()) with check(public.is_teacher() and exists(select 1 from public.poem_contest_roster s where s.id=student_id and s.active and upper(regexp_replace(s.group_name,'\s','','g'))=group_key));
create function public.teacher_poem_dashboard() returns jsonb language plpgsql security invoker set search_path='' as $$
begin
 if auth.uid() is null or not public.is_teacher() then raise exception 'No autorizado';end if;
 return jsonb_build_object('ok',true,'catalog',coalesce((select jsonb_agg(to_jsonb(c) order by c.number) from public.poem_contest_catalog c),'[]'::jsonb),'students',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'group',s.group_name,'group_key',upper(regexp_replace(s.group_name,'\s','','g')),'number',s.list_number,'poem_number',r.poem_number,'chosen_at',r.chosen_at) order by s.group_name,s.list_number,s.name) from public.poem_contest_roster s left join public.poem_contest_reservations r on r.student_id=s.id and r.cycle='2026-2027' and r.active where s.active),'[]'::jsonb));
end $$;
create function public.teacher_reserve_poem(p_student_id text,p_poem_number integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare g text; old public.poem_contest_reservations; holder text;
begin
 if auth.uid() is null or not public.is_teacher() then raise exception 'No autorizado';end if;
 select upper(regexp_replace(s.group_name,'\s','','g')) into g from public.poem_contest_roster s where s.id=p_student_id and s.active;
 if g is null then raise exception 'Alumno no disponible en vespertino';end if;
 select * into old from public.poem_contest_reservations where student_id=p_student_id and cycle='2026-2027' and active;
 if p_poem_number is not null and not exists(select 1 from public.poem_contest_catalog where number=p_poem_number) then raise exception 'Número de poema inválido';end if;
 if old.poem_number=p_poem_number then return jsonb_build_object('ok',true,'unchanged',true);end if;
 if p_poem_number is not null then
  select s.name into holder from public.poem_contest_reservations r join public.poem_contest_roster s on s.id=r.student_id where r.cycle='2026-2027' and r.group_key=g and r.canonical_number=case when p_poem_number=16 then 9 else p_poem_number end and r.active and r.student_id<>p_student_id;
  if holder is not null then return jsonb_build_object('ok',false,'reason','Ese poema ya lo eligió '||holder||' en este grupo.');end if;
 end if;
 update public.poem_contest_reservations set active=false,released_at=now() where student_id=p_student_id and cycle='2026-2027' and active;
 if p_poem_number is not null then insert into public.poem_contest_reservations(student_id,group_key,poem_number) values(p_student_id,g,p_poem_number);end if;
 return jsonb_build_object('ok',true);
exception when unique_violation then return jsonb_build_object('ok',false,'reason','Otro alumno acaba de reservar ese poema. Actualiza para ver quién lo eligió.');
end $$;
revoke execute on function public.teacher_poem_dashboard(),public.teacher_reserve_poem(text,integer) from public,anon;
grant execute on function public.teacher_poem_dashboard(),public.teacher_reserve_poem(text,integer) to authenticated;
commit;
